const INK = COLORS.navy;
const STROKE_FACE = 7.5;
const CX = 180; // pusat wajah

const Eyes: React.FC<{ y?: number }> = ({ y = 161 }) => (
  <>
    <ellipse cx={CX - 38.5} cy={y} rx={7.5} ry={10.5} fill={INK} />
    <ellipse cx={CX + 38.5} cy={y} rx={7.5} ry={10.5} fill={INK} />
  </>
);

const line = {
  fill: "none",
  stroke: INK,
  strokeWidth: STROKE_FACE,
  strokeLinecap: "round",
  strokeLinejoin: "round",
} as const;

/** Wajah per tingkat mood. Lengkung memakai busur agar ujungnya membulat seperti aslinya. */
export const Face: React.FC<{ mood: MoodLevel }> = ({ mood }) => {
  switch (mood) {
    case 1: // mata terpejam, mulut cemberut
      return (
        <>
          <path d={`M${CX - 54} 159 A15 10 0 0 0 ${CX - 24} 159`} {...line} />
          <path d={`M${CX + 24} 159 A15 10 0 0 0 ${CX + 54} 159`} {...line} />
          <path d={`M${CX - 16} 198 A16 14 0 0 1 ${CX + 16} 198`} {...line} />
        </>
      );
    case 2: // mata titik, cemberut
      return (
        <>
          <Eyes />
          <path d={`M${CX - 17} 199 A17 15 0 0 1 ${CX + 17} 199`} {...line} />
        </>
      );
    case 3: // mata titik, mulut datar
      return (
        <>
          <Eyes />
          <path d={`M${CX - 21} 187 L${CX + 21} 187`} {...line} />
        </>
      );
    case 4: // senyum kecil
      return (
        <>
          <Eyes />
          <path d={`M${CX - 21} 186 A21 15 0 0 0 ${CX + 21} 186`} {...line} />
        </>
      );
    case 5: // senyum lebar, mulut terbuka
      return (
        <>
          <Eyes y={157} />
          <path
            d={`M${CX - 23} 181 H${CX + 23} C${CX + 23} 199 ${CX + 13} 209 ${CX} 209 C${CX - 13} 209 ${CX - 23} 199 ${CX - 23} 181 Z`}
            {...line}
          />
        </>
      );
  }
};

export type BlobProps = {
  /** Menentukan wajah dan warna isi bawaan. */
  mood: MoodLevel;
  /** Lebar dan tinggi kotak blob dalam px. */
  size: number;
  /** Ganti warna isi (mis. saat berubah warna). */
  fill?: string;
  /** Ganti wajah tanpa mengubah warna. */
  face?: MoodLevel;
  /** Skala horizontal/vertikal untuk squash and stretch (1 = normal). */
  scaleX?: number;
  scaleY?: number;
  /** Napas pelan terus-menerus (amplitudo 3%, periode 2,4 dtk). */
  breathe?: boolean;
  /** Geser fase napas (detik) agar blob tidak bernapas serempak. */
  breathePhaseSec?: number;
  style?: CSSProperties;
};

export const Blob: React.FC<BlobProps> = ({
  mood,
  size,
  fill,
  face,
  scaleX = 1,
  scaleY = 1,
  breathe = false,
  breathePhaseSec = 0,
  style,
}) => {
  const frame = useCurrentFrame();
  const b = breathe ? breath(frame, 0.03, 2.4, breathePhaseSec) : 1;
  return (
    <div
      style={{
        width: size,
        height: size,
        transform: `scale(${scaleX * b}, ${scaleY * b})`,
        transformOrigin: "50% 88%", // alas blob tetap menempel saat memipih
        ...style,
      }}
    >
      <svg
        viewBox="0 0 360 360"
        width={size}
        height={size}
        style={{ display: "block", overflow: "visible" }}
      >
        <path
          d={BLOB_PATH}
          fill={fill ?? MOOD_FILL[mood]}
          stroke={INK}
          strokeWidth={8.5}
          strokeLinejoin="round"
        />
        <Face mood={face ?? mood} />
      </svg>
    </div>
  );
};
